// Mechanical reference packing and delivery export; scene art is generated by imagegen.
const fs = require('node:fs');
const path = require('node:path');
const sharp = require('sharp');
const root = path.resolve(__dirname, '../..');
const review = path.join(__dirname, 'story-scene-review');
async function main() {
  if (process.argv[2] === '--references') {
    const output = path.join(review, 'kangwoo-leo-identity-reference.png');
    const images = await Promise.all(['kangwoo', 'leo'].map(async id => {
      const input = path.join(root, 'assets/portraits', id + '.png');
      const metadata = await sharp(input).metadata();
      return { input: await sharp(input).png().toBuffer(), width: metadata.width, height: metadata.height };
    }));
    await sharp({create:{width:images[0].width + images[1].width,height:Math.max(...images.map(x=>x.height)),channels:3,background:'#18202a'}})
      .composite([{input:images[0].input,left:0,top:0},{input:images[1].input,left:images[0].width,top:0}]).png().toFile(output);
    console.log(output);
    return;
  }
  const source = process.argv[2];
  if (!source || !fs.existsSync(source)) throw new Error('Pass the imagegen output path.');
  const master = path.join(review, 'masters/pair-kangwoo-leo-replay-v1.png');
  const delivery = path.join(root, 'assets/scenes/pair-kangwoo-leo-replay-v1.webp');
  if (fs.existsSync(master) || fs.existsSync(delivery)) throw new Error('Refusing to replace an existing version.');
  fs.mkdirSync(path.dirname(master), {recursive:true});
  fs.copyFileSync(source, master);
  await sharp(master).rotate().resize(1024,576,{fit:'cover',position:'centre'}).toColourspace('srgb').webp({quality:86,effort:6}).toFile(delivery);
  console.log(JSON.stringify({master,delivery,metadata:await sharp(delivery).metadata()}));
}
main().catch(error=>{console.error(error);process.exitCode=1;});
